CREATE TABLE "blood_glucose_readings" ("id" TEXT NOT NULL, "patient_id" TEXT NOT NULL REFERENCES patients (id) ON DELETE CASCADE, "recorded_at" INTEGER NOT NULL, "value_mg_dl" REAL NOT NULL, "context" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "blood_pressure_readings" ("id" TEXT NOT NULL, "patient_id" TEXT NOT NULL REFERENCES patients (id) ON DELETE CASCADE, "recorded_at" INTEGER NOT NULL, "systolic" INTEGER NULL, "diastolic" INTEGER NULL, "heart_rate_bpm" INTEGER NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "fluid_intake_logs" ("id" TEXT NOT NULL, "patient_id" TEXT NOT NULL REFERENCES patients (id) ON DELETE CASCADE, "recorded_at" INTEGER NOT NULL, "fluid_ml" REAL NOT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "medications" ("id" TEXT NOT NULL, "pharmaceutical_name" TEXT NOT NULL, "composition" TEXT NOT NULL, "about" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "patient_medication_schedules" ("id" TEXT NOT NULL, "patient_id" TEXT NOT NULL UNIQUE REFERENCES patients (id) ON DELETE CASCADE, "schedule" TEXT NOT NULL DEFAULT '{"by_day":{}}', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "patient_prefs" ("id" TEXT NOT NULL, "patient_id" TEXT NOT NULL UNIQUE REFERENCES patients (id) ON DELETE CASCADE, "weight_unit" TEXT NOT NULL DEFAULT 'kg', "blood_glucose_unit" TEXT NOT NULL DEFAULT 'mg_dl', "daily_water_goal_ml" INTEGER NOT NULL DEFAULT 1200, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "patients" ("id" TEXT NOT NULL, "auth_user_id" TEXT NOT NULL UNIQUE, "first_name" TEXT NULL, "last_name" TEXT NULL, "date_of_birth" INTEGER NULL, "sex" TEXT NULL, "ckd_stage" TEXT NULL, "dialysis_type" TEXT NOT NULL DEFAULT 'none', "dialysis_days_of_week" TEXT NULL, "height_cm" REAL NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "sync_state" ("table_key" TEXT NOT NULL, "last_pulled_at" INTEGER NULL, "last_synced_run_at" INTEGER NULL, PRIMARY KEY ("table_key"));
CREATE TABLE "weight_readings" ("id" TEXT NOT NULL, "patient_id" TEXT NOT NULL REFERENCES patients (id) ON DELETE CASCADE, "recorded_at" INTEGER NOT NULL, "value_kg" REAL NOT NULL, "dialysis_timing" TEXT NOT NULL DEFAULT 'non_dialysis', "weight_context" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "is_dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("is_dirty" IN (0, 1)), PRIMARY KEY ("id"));
